 13→// --- ParseHookEvent: agent-spawn ---
 14→
 15→func TestParseHookEvent_AgentSpawn(t *testing.T) {
 16→	t.Parallel()
 17→
 18→	tempDir := t.TempDir()
 19→	// Create a minimal git repo so paths.WorktreeRoot works, or rely on fallback to ".".
 20→	// Since we're parallel, we can't chdir. The cache will write to "./.entire/tmp/" relative
 21→	// to the test process's cwd. That's fine: we just verify event fields, not the cache file.
 22→
 23→	ag := &KiroAgent{}
 24→	input := `{"hook_event_name":"agentSpawn","cwd":"` + tempDir + `"}`
 25→
 26→	event, err := ag.ParseHookEvent(context.Background(), HookNameAgentSpawn, strings.NewReader(input))
 27→
 28→	if err != nil {
 29→		t.Fatalf("unexpected error: %v", err)
 30→	}
 31→	if event == nil {
 32→		t.Fatal("expected event, got nil")
 33→	}
 34→	if event.Type != agent.SessionStart {
 35→		t.Errorf("expected event type %v, got %v", agent.SessionStart, event.Type)
 36→	}
 37→	if event.SessionID == "" {
 38→		t.Error("expected non-empty session ID")
 39→	}
 40→	if event.Timestamp.IsZero() {
 41→		t.Error("expected non-zero timestamp")
 42→	}
 43→}
