126→func TestParseHookEvent_Stop_TranscriptRef(t *testing.T) {
127→	tempDir := t.TempDir()
128→	t.Chdir(tempDir)
129→	t.Setenv("ENTIRE_TEST_KIRO_MOCK_DB", "1")
130→
131→	ag := &KiroAgent{}
132→
133→	// First, agent-spawn to generate and cache a session ID.
134→	spawnInput := `{"hook_event_name":"agentSpawn","cwd":"` + tempDir + `"}`
135→	spawnEvent, err := ag.ParseHookEvent(context.Background(), HookNameAgentSpawn, strings.NewReader(spawnInput))
136→	if err != nil {
137→		t.Fatalf("agent-spawn error: %v", err)
138→	}
139→
140→	// Then stop — should set SessionRef to cached transcript path.
141→	stopInput := `{"hook_event_name":"stop","cwd":"` + tempDir + `"}`
142→	stopEvent, err := ag.ParseHookEvent(context.Background(), HookNameStop, strings.NewReader(stopInput))
143→	if err != nil {
144→		t.Fatalf("stop error: %v", err)
145→	}
146→
147→	if stopEvent.SessionRef == "" {
148→		t.Fatal("stop event SessionRef should not be empty when mock DB is enabled")
149→	}
150→
151→	// Verify the path contains the session ID and ends with .json.
152→	if !strings.Contains(stopEvent.SessionRef, spawnEvent.SessionID) {
153→		t.Errorf("SessionRef %q does not contain session ID %q", stopEvent.SessionRef, spawnEvent.SessionID)
154→	}
155→	if !strings.HasSuffix(stopEvent.SessionRef, ".json") {
156→		t.Errorf("SessionRef %q does not end with .json", stopEvent.SessionRef)
157→	}
158→}
